  --tl-paper:#f4f9fb;--tl-card:#fff;--tl-ink:#183c4a;--tl-muted:#355766;
  --tl-line:#68828d;--tl-focus:#075f78;--tl-cold:#d6edf4;--tl-warm:#fbe8ce;
  --tl-path:#174f64;--tl-cold-ink:#245c72;--tl-warm-ink:#774811;
  margin:12px 0;border:1px solid var(--tl-line);border-radius:16px;
  background:var(--tl-paper);color:var(--tl-ink);min-width:0;
}
.dark .wc-thermal-layer-inspector,.wc-thermal-layer-inspector.is-dark {
  --tl-paper:#102d38;--tl-card:#173b48;--tl-ink:#eefbff;--tl-muted:#c7dfe8;
  --tl-line:#7195a3;--tl-focus:#82e4ef;--tl-cold:#234f63;--tl-warm:#59432c;
  --tl-path:#b9edf7;--tl-cold-ink:#c1edf9;--tl-warm-ink:#ffe0ad;
}
.wc-thermal-layer-inspector.is-contrast {
  --tl-paper:#fff;--tl-card:#fff;--tl-ink:#111;--tl-muted:#222;--tl-line:#111;
  --tl-focus:#005269;--tl-cold:#e9f3f7;--tl-warm:#fff1dc;--tl-path:#111;
  --tl-cold-ink:#123b4b;--tl-warm-ink:#603700;
}
.wc-precip-lab .wc-thermal-layer-inspector>summary {
  min-height:48px;box-sizing:border-box;padding:13px 14px;cursor:pointer;
  color:var(--tl-ink);font-size:15px;font-weight:750;line-height:1.45;
}
.wc-tl-body {container:thermal-inspector / inline-size;padding:0 12px 14px;min-width:0}
.wc-precip-lab .wc-thermal-layer-inspector p {font-size:14px;line-height:1.6;color:var(--tl-muted);margin:8px 0;overflow-wrap:anywhere}
.wc-precip-lab .wc-thermal-layer-inspector h4,.wc-precip-lab .wc-thermal-layer-inspector h5 {
  color:var(--tl-ink);font-size:16px;line-height:1.45;margin:0 0 8px;
}
.wc-tl-layout {display:grid;grid-template-columns:1fr;gap:14px}
.wc-tl-chart {padding:12px;border:1px solid var(--tl-line);border-radius:12px;background:var(--tl-card);min-width:0}
.wc-tl-chart-title {display:block;font-size:14px;line-height:1.4;margin-bottom:10px;color:var(--tl-ink)}
.wc-tl-zones,.wc-tl-axis {display:flex;justify-content:space-between;gap:8px;font-size:13px;line-height:1.4;color:var(--tl-ink)}
.wc-tl-zones span:first-child {color:var(--tl-cold-ink)}
.wc-tl-zones span:last-child {color:var(--tl-warm-ink)}
.wc-tl-axis {position:relative;height:20px;margin-top:6px}
.wc-tl-axis span {position:absolute;top:0}
.wc-tl-axis span:first-child {left:6.67%}
.wc-tl-axis span:nth-child(2) {left:50%;transform:translateX(-50%)}
.wc-tl-axis span:last-child {right:6.67%}
.wc-tl-plot {display:block;width:100%;height:228px;margin-top:8px;border-radius:10px}
.wc-tl-cold {fill:var(--tl-cold)}.wc-tl-warm {fill:var(--tl-warm)}
.wc-tl-hatch {fill:none;stroke:var(--tl-cold-ink);stroke-width:1;opacity:.28}
.wc-tl-guide {stroke:var(--tl-line);stroke-width:1;fill:none;vector-effect:non-scaling-stroke}
.wc-tl-zero {stroke:var(--tl-path);stroke-width:1.5;stroke-dasharray:3 4;vector-effect:non-scaling-stroke}
.wc-tl-cross {stroke:var(--tl-path);stroke-width:1.5;stroke-dasharray:7 4;vector-effect:non-scaling-stroke;fill:var(--tl-card)}
.wc-tl-path {fill:none;stroke:var(--tl-path);stroke-width:3;vector-effect:non-scaling-stroke}
.wc-tl-point {fill:var(--tl-card);stroke:var(--tl-path);stroke-width:2;vector-effect:non-scaling-stroke}
.wc-tl-point[data-selected=true] {fill:var(--tl-path);stroke:var(--tl-card);stroke-width:2}
.wc-tl-selected-ring {fill:none;stroke:var(--tl-path);stroke-width:2;vector-effect:non-scaling-stroke}
.wc-tl-crossing-list {display:grid;gap:8px;margin:12px 0 0;padding:0;list-style:none;font-size:13px;line-height:1.5;color:var(--tl-muted)}
.wc-tl-crossing-list li {padding:8px;border:1px dashed var(--tl-line);border-radius:8px}
.wc-tl-crossing-list strong {color:var(--tl-ink)}
.wc-tl-nodes {display:grid;gap:8px;align-content:start;min-width:0}
.wc-precip-lab .wc-tl-node {
  width:100%;min-height:76px;text-align:left;display:grid;grid-template-columns:1fr auto;gap:5px 8px;
  padding:11px 12px;border:1px solid var(--tl-line);border-radius:12px;
  background:var(--tl-card);color:var(--tl-ink);font:inherit;font-size:14px;line-height:1.5;cursor:pointer;
}
.wc-tl-node>strong {font-size:15px}.wc-tl-node>span {grid-column:1/-1;color:var(--tl-muted);font-size:13px}
.wc-tl-node>em {font-size:13px;font-style:normal;font-weight:700}
.wc-precip-lab .wc-tl-node[aria-pressed=true] {border:2px solid var(--tl-focus);padding:10px 11px}
.wc-tl-node-temperature {font-variant-numeric:tabular-nums;white-space:nowrap;font-weight:750}
.wc-tl-detail,.wc-tl-surface,.wc-tl-question {margin-top:14px;padding:12px;border:1px solid var(--tl-line);border-radius:12px;background:var(--tl-card);min-width:0}
.wc-tl-detail-head {display:flex;align-items:center;gap:12px}
.wc-tl-particle {width:52px;height:52px;flex:0 0 52px;fill:var(--tl-cold);stroke:var(--tl-path);stroke-width:2.3;stroke-linecap:round;stroke-linejoin:round}
.wc-tl-reading {display:grid;grid-template-columns:1fr;gap:10px;margin:12px 0}
.wc-tl-reading>div {padding:10px;border:1px solid var(--tl-line);border-radius:10px;background:var(--tl-paper);min-width:0}
.wc-tl-reading dt {font-size:13px;line-height:1.4;color:var(--tl-muted);margin-bottom:4px}
.wc-tl-reading dd {font-size:15px;line-height:1.5;font-weight:750;margin:0;color:var(--tl-ink)}
.wc-tl-surface>strong {font-size:14px;color:var(--tl-ink);line-height:1.5}
.wc-precip-lab .wc-tl-question>summary {min-height:44px;box-sizing:border-box;padding:9px 0;font-size:14px;line-height:1.5;font-weight:750;cursor:pointer;color:var(--tl-ink)}
.wc-tl-answers {display:grid;gap:8px}
.wc-precip-lab .wc-tl-answers button {min-height:44px;border:1px solid var(--tl-line);border-radius:9px;background:var(--tl-paper);color:var(--tl-ink);padding:10px 12px;font:inherit;font-size:14px;line-height:1.5;text-align:left;cursor:pointer}
.wc-precip-lab .wc-tl-answers button[aria-pressed=true] {border:2px solid var(--tl-focus);padding:9px 11px;font-weight:750}
.wc-tl-feedback {margin-top:12px;padding:12px;border-left:3px solid var(--tl-focus);background:var(--tl-paper);border-radius:0 9px 9px 0}
.wc-precip-lab .wc-thermal-layer-inspector :is(button,summary,h4,h5):focus-visible {outline:3px solid var(--tl-focus);outline-offset:3px}
@container thermal-inspector (min-width:560px) {.wc-tl-layout {grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.wc-tl-reading {grid-template-columns:1fr 1fr}}
@media(forced-colors:active) {
  .wc-thermal-layer-inspector {--tl-paper:Canvas!important;--tl-card:Canvas!important;--tl-ink:CanvasText!important;--tl-muted:CanvasText!important;--tl-line:CanvasText!important;--tl-focus:Highlight!important;--tl-cold:Canvas!important;--tl-warm:Canvas!important;--tl-path:CanvasText!important;--tl-cold-ink:CanvasText!important;--tl-warm-ink:CanvasText!important;forced-color-adjust:none}
  .wc-precip-lab .wc-thermal-layer-inspector button {background:ButtonFace!important;color:ButtonText!important;border-color:ButtonText!important}
  .wc-tl-hatch {opacity:1}
}
